export function BotMark({ bot, filled }: { bot: Pick<Bot, "icon" | "color">; filled?: boolean }) {
  const glyph = bot.icon === "hat" ? undefined : BOT_PATHS[bot.icon];
  return (
    <svg
      className="i"
      viewBox="0 -960 960 960"
      aria-hidden="true"
      style={{ color: `var(--bot-${bot.color})` }}
    >
      {glyph ? <SymbolPath glyph={glyph} filled={filled} /> : <Hat filled={filled} />}
    </svg>
  );
}
